export const lsConcepts101200: any[] = [
  { id: "ls-nama-101", title: "Maṇipūrāntaruditā", category: "Kuṇḍalinī", summary: "She who emerges in the maṇipūra cakra. Literally the name places Her risen within the navel wheel, jewel-city of the body, where She sits adorned as upon a throne. Doctrinally the passage presents this cakra through a storm image of a dark cloud shot with Śakti-lightning, gem-rainbow, and cooling rain that relieves worlds scorched by inner fire and sun, while deep meditation may reveal a luminous bow there. This marks Her whole ascent as both royal progress and weather of grace. Contemplate the navel region as Her court and rest attention where heat turns to rain. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 38.)", relatedVerseIds: ["ls-038"] },
  { id: "ls-nama-102", title: "Viṣṇugranthivibhedinī", category: "Kuṇḍalinī", summary: "She who breaks through the knot of viṣṇu. The compound joins the preserver's name with piercing, locating this second knot just above the navel wheel where Viṣṇu presides. Its doctrinal sense is that sustenance itself becomes a bond: ordinary life depends on being maintained, so passing this knot means living beyond mere maintenance, supported instead by the inner nectar that frees sages and yogins from outer supply. The ascent is thus graded from survival to freedom. Contemplate what in you still begs to be sustained, and offer that dependence upward until She cuts it. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 38.)", relatedVerseIds: ["ls-038"] },
  { id: "ls-nama-103", title: "Ājñācakrāntarālasthā", category: "Kuṇḍalinī", summary: "She who resides at the center of the Ājñā chakra. The name means She dwells in the interval of the command wheel, the brow center also called the third eye. Doctrinally this is the last of the six wheels and the seat from which the guru inwardly commands; after the five elemental centers, mind itself becomes the instrument, so a first direct taste of Brahman dawns here amid supreme radiance flanked by pure awareness. The gift of divine sight replaces physical seeing. Contemplate the brow as a listening post, receiving instruction rather than projecting desire. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 39.)", relatedVerseIds: ["ls-039"] },
  { id: "ls-nama-104", title: "Rudragranthivibhedinī", category: "Kuṇḍalinī", summary: "She who breaks through the knot of shiva. Rudra's knot is the third and final constriction, barring the crown, and She alone bursts it to proceed upward. The passage links each knot with a seed-syllable of the fifteen-syllabled mantra, so that mantra, moon-digits, fire, sun, and lunar currents all converge in this piercing; once crossed, latent impressions fall away, lesser centers between brow and crown are traversed, and supreme knowing opens with the joy of near-homecoming and ready grace. Contemplate the last resistance in your own meditation as already loosening, and ask Her blessing at the threshold. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 39.)", relatedVerseIds: ["ls-039"] },
  { id: "ls-nama-105", title: "Sahasrārāmbujārūḍhā", category: "Kuṇḍalinī", summary: "She who ascends to the thousand-petaled lotus. The image is of climbing and mounting the crown lotus beneath the cranial aperture that opens to the cosmos. There the long-separate partners unite, and the practitioner who worshipped energy alone now honors the pair together. The thousand petals are read through sacred arithmetic, fifty sound-powers multiplied by twenty principles of elements, senses, actions, and subtle essences, making the crown a complete alphabet of manifestation. Contemplate the crown as a full-blown lotus receiving Her, and let worship widen from one power to the union. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 39.)", relatedVerseIds: ["ls-039"] },
  { id: "ls-nama-106", title: "Sudhāsārābhivarṣiṇī", category: "Kuṇḍalinī", summary: "She who pours out streams of ambrosia. Sudhā is nectar, sāra its essence, and varṣiṇī the rain that showers it down. Doctrinally Her arrival at the crown's lunar center generates heat that melts stored nectar, which then drips through the throat and floods every channel, drenching the nerves from Her feet downward; lunar and consciousness-moons mirror the sacred diagram, both shedding the same life-fluid from the region of Her feet. Grace here is literally irrigation. Contemplate cool nectar descending through the throat with each breath, soothing and vitalizing the whole frame. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 39.)", relatedVerseIds: ["ls-039"] },
  { id: "ls-nama-107", title: "Taḍillatāsamaruciḥ", category: "Kuṇḍalinī", summary: "She who is as beautiful as a flash of lightning. Taḍit is lightning and latā its slender streak, so the name compares Her radiance to a sudden luminous line. The passage saves this image for the moment of union: the whole spinal channel is said to kindle like lightning only when She rests with Her Lord, disclosing both as Brahman, motionless ground and empowered manifestation together, neither effective alone. Sudden Self-recognition likewise splits ignorance in an instant. Variant readings of the first syllable change nothing in sense. Contemplate the spine as a brief, brilliant flash rather than a steady lamp, and be ready for insight without warning. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 40.)", relatedVerseIds: ["ls-040"] },
  { id: "ls-nama-108", title: "Ṣaṭcakroparisaṃsthitā", category: "Kuṇḍalinī", summary: "She who resides above the six cakrās. The name stations Her beyond the sextet from root to brow, enthroned in the crown which itself is no ordinary wheel. Doctrinally the lower six belong to worldly function, while the summit stands for Brahman beyond function; to realize Her there one must have crossed every instrumental level rather than merely refined it. Height here means transcendence, not distance. Contemplate each lower center as a rung already beneath you, and lift attention to what needs no wheel to turn. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 40.)", relatedVerseIds: ["ls-040"] },
  { id: "ls-nama-109", title: "Mahāsaktiḥ", category: "Kuṇḍalinī", summary: "She who is greatly attached to the festive union of shiva and shakti. Mahas suggests festival and asakti loving attachment, so the name celebrates Her delight in reunion. The commentary distinguishes inner festival of mind from outer festival of body, prizing the inward worship of the coiled power while also reading the syllables as supreme power spread on every side. Her joy is thus both occasion and omnipresence. Contemplate meditation itself as festivity, decorating the inner shrine rather than merely disciplining the mind, until practice feels like celebration. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 40.)", relatedVerseIds: ["ls-040"] },
  { id: "ls-nama-110", title: "Kuṇḍalinī", category: "Kuṇḍalinī", summary: "She who has the form a coil. The bare name identifies Her with the thrice-and-half coiled serpent asleep in the root wheel, vital breath resting amid bodily fire whose disturbance breeds illness. A faint inner hissing, audible when the ears are sealed, recalls Her presence, while the triangular base of will, knowledge, and action utters the syllables of the sacred monosyllable; ancient yoga lore calls Her delicate, hissing, mind-shaking, purified only by knowledge-rays binding every channel. One word thus carries the whole subtlest form. Contemplate the coiled stillness at the base, listening for its hiss as for a sleeping serpent's breath. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 40.)", relatedVerseIds: ["ls-040"] },
  { id: "ls-nama-111", title: "Bisatantutanīyasī", category: "Kuṇḍalinī", summary: "She who is fine and delicate as the fiber of the lotus. Bisa-tantu is the hair-fine lotus filament, tanīyasī its extreme slenderness, closing the subtlest-form sequence with minuteness. The passage pictures Her as maiden sounding below, bride adorned at the navel, spouse hastening crownward through a nearly invisible middle canal that lightnings when unblocked; immense capacities may surface en route, and misuse bars realization and invites rebuke, for She remembers how each center was used even while burning toward union. Paired with the supreme name before it, smallness and greatness coincide. Contemplate the central channel as finer than thread yet mightier than storm. Knots (granthis) mark where identity clings — to body, to personality, to transcendence itself — and each piercing is a letting-go. (Stotra verse 40.)", relatedVerseIds: ["ls-040"] },
  { id: "ls-nama-112", title: "Bhavānī", category: "Bhakti", summary: "She who is the wife of bhava (shiva). Bhava names the Lord as origin and sustainer, while ana suggests infusion of life, so His consort is the universal life-giver who even restored the love-god. Doctrinally the famous hymn-verse plays on address and becoming: едва the devotee cries to the consort of Bhava, She grants absorption into Herself, servant dissolving into God-consciousness. Grammar differs between Lord and Lady, yet their act is one. Contemplate calling Her by this intimate name until the caller herself begins to become what she invokes. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 41.)", relatedVerseIds: ["ls-041"] },
  { id: "ls-nama-113", title: "Bhāvanāgamyā", category: "Bhakti", summary: "She who is unattainable through imagination or thought. Bhāvanā here means disciplined contemplative attention rather than fantasy, so the name says She is reached only through inward worship. The passage points to the Upaniṣad of contemplation, where outer diagram-rituals fall away of themselves and knower, knowledge, and known unite; it further distinguishes repeating a mantra from dwelling in its meaning, the latter being stronger, always under a teacher's guidance through unstained awareness. Outward rite must ripen into meditation. Contemplate daily whether practice is still performance, and turn one ritual act into silent knowing-union. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 41.)", relatedVerseIds: ["ls-041"] },
  { id: "ls-nama-114", title: "Bhavāraṇyakuṭhārikā", category: "Bhakti", summary: "She who is like an axe to clear the jungle of samsāra. The forest is transmigratory existence grown thick with desire, attachment, and affection; an axe must fell every trunk and grub out roots, or shoots return and bondage renews its cycle. Doctrinally She wields this axe not indiscriminately but for those who invoke Her as Bhavānī and pursue the inward contemplative discipline, whose mental worship alone earns the clearing. Grace completes effort by extirpation. Contemplate one persistent root-tendency rather than many branches, and place it before Her axe each sitting. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 41.)", relatedVerseIds: ["ls-041"] },
  { id: "ls-nama-115", title: "Bhadrapriyā", category: "Bhakti", summary: "She who is fond of all auspicious things - who gives all auspicious things. Bhadra means the blessed and beneficial, priyā loving and bestowing, so the name makes benefaction Her pleasure. Devotees here are simply those striving toward Her by any valid means, and Her sacred feet are the instruments of favor, eager rather than reluctant to bless. Liking and giving are one gesture in a mother. Contemplate approaching Her feet as the natural venue of help, expecting generosity rather than bargaining for it. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 41.)", relatedVerseIds: ["ls-041"] },
  { id: "ls-nama-116", title: "Bhadramūrtiḥ", category: "Bhakti", summary: "She who is the embodiment of auspiciousness or benevolence. Mūrti declares that blessing is not merely what She does but what She is. The passage equates this with calling Her the auspicious Lord Himself, since auspiciousness belongs properly to Brahman alone, acclaimed elsewhere as the most auspicious among auspicious things; Her very form is therefore welfare made visible. To see Her is already to be blessed. Contemplate Her figure as condensed good fortune, letting sight itself quiet apprehension. Her auspiciousness is not seasonal favor but ontology: where She is present, welfare follows as light follows flame, and beholding Her steadies the frightened mind more surely than argument. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 41.)", relatedVerseIds: ["ls-041"] },
  { id: "ls-nama-117", title: "Bhaktasaubhāgyadāyinī", category: "Bhakti", summary: "She who confers prosperity on Her devotees. Saubhāgya is wedded fortune in its widest sense, and She distributes it to those turned toward Her. The commentary recalls an eightfold prosperity list of cane, sacred fig, sprouted spices, coriander, milk and its transformations, yellow-hued goods, flowers, and salt, all tokens of increase and well-being that outer emblems only hint at. True fortune remains Her gift, not accident. Contemplate one concrete good you have received as dealt from Her hand, and gratitude will invite further increase. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 41.)", relatedVerseIds: ["ls-041"] },
  { id: "ls-nama-118", title: "Bhaktipriyā", category: "Bhakti", summary: "She who is fond of (and pleased by) devotion. Priyā marks delight, so the name says devotion itself pleases Her more than display. The passage gathers classic images of needle seeking magnet, creeper embracing tree, river entering ocean, and mind reaching the divine feet, with devotion described as beyond the three qualities, beyond craving, growing each instant, bound to Brahman and known only by tasting; stagnant feeling must become flood, since inquiry into one's own nature is itself devotion. No obstacle detains a true lover. Contemplate whether your feeling flows or ponds, and remove one small dam today. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 42.)", relatedVerseIds: ["ls-042"] },
  { id: "ls-nama-119", title: "Bhaktigamyā", category: "Bhakti", summary: "She who is attained only through devotion. Gamyā restricts the approach: pure devotion alone arrives, since She loves exactly that. The passage supports exclusivity with many voices, realization dawning in absorption through revelation and inference, devotion to Brahman conferring deathlessness and union, outward senses corrected inward, truth-knowledge-infinity as Brahman, and devoted service opening direct vision and entry into the divine kingdom. Knowledge and devotion thus converge at the summit. Contemplate shifting weight from technique to love, measuring practice by tenderness rather than duration. A companion litany repeats the same exclusivity, confirming that the paths of love and of knowing meet at one door, since grace opens only to the heart already turned. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 42.)", relatedVerseIds: ["ls-042"] },
  { id: "ls-nama-120", title: "Bhaktivaśyā", category: "Bhakti", summary: "She who is to be won over by devition. Vaśyā means brought under loving control, so devotion attracts and gently governs Her. The commentary calls the Mother's very name devotion and pictures Her nursing the devotee as Her child, with overwhelming feeling shown in tears, choked voice, horripilation, and tremor; the stark tale of the hunter-saint who offered wild food and finally his own eyes illustrates a love beyond rubric gladly accepted. Feeling rules where rule fails. Contemplate offering one raw, unpolished act of love without ritual apology, trusting She accepts the heart before the form. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 42.)", relatedVerseIds: ["ls-042"] },
  { id: "ls-nama-121", title: "Bhayāpahā", category: "Bhakti", summary: "She who dispels fear. Apahā removes, bhaya the dread born of perceiving a second where none exists. The passage argues from non-duality: knowing Brahman leaves none beside oneself, so fear loses its object, the apparent other being ignorance woven by illusion; mere utterance of Her name is said to protect, Her feet to shelter the frightened, while deeper reading names the whole round of birth and death as the fear She cures, a destroyer of spiritual progress rooted in mind. Contemplate fear as mistaken duality, and repeat Her name until the second vanishes. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 42.)", relatedVerseIds: ["ls-042"] },
  { id: "ls-nama-122", title: "Śāmbhavī", category: "Bhakti", summary: "She who is the wife of shambhu (shiva). Śambhu is the benign source of comfort, and His consort shares that consoling office toward devotees. The name further evokes the brow-gaze discipline that lifts awareness upward, one of three modes of initiation alongside energy and mantra transmissions, while Her children in this lineage are called after Him; hymn verses naming Her His very body and bride stress inseparable physical and mental union, and an eight-year maiden form honored in virgin-worship promises prosperity rightly performed. Comfort here is initiation. Contemplate turning both eyes inward and upward, resting as His body and bride in one. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 42.)", relatedVerseIds: ["ls-042"] },
  { id: "ls-nama-123", title: "Śāradārādhyā", category: "Bhakti", summary: "She who is worshipped by śaradā (sarasvatī, the goddess of speech). Śāradā is the speech-goddess and by extension the seer-poetesses themselves, so the highest learning bows to Her. The passage also hears the autumn nine-nights festival, when night-worship belongs to the Goddess as morning to the Preserver and evening to the Lord, with a spring nine-nights as counterpart; an old tale of gods awakening Her on a spring ninth day explains the seasonal name. Knowledge culminates in adoration. Contemplate offering speech itself, studying little but praising deeply, especially after nightfall. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 42.)", relatedVerseIds: ["ls-042"] },
  { id: "ls-nama-124", title: "Śarvāṇī", category: "Bhakti", summary: "She who is the wife of sharva (shiva). Śarva is the Lord's earthy cosmic embodiment among His eight elemental, psychic, and luminous forms set forth in old lore, earth and water grounding the rest. His consort therefore weds transcendence to dense matter, with the red planet counted as their offspring. The passage uses this to warn that planetary remedy demands precise stellar timing, feeding of the hungry, and personal mantra effort rather than mechanical rite on a weekday. Even astrology bends toward ethics and devotion. Contemplate your heaviest material concern as already held within Her marriage to earth. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 42.)", relatedVerseIds: ["ls-042"] },
  { id: "ls-nama-125", title: "Śarmadāyinī", category: "Bhakti", summary: "She who confers happiness. Śarma is shelter-joy, and giving it is described as Her maternal habit rather than occasional favor. As universal Mother She naturally settles Her children into well-being, a theme resumed in later names of delight and beatitude. Happiness here is protection ripened into gladness. Contemplate receiving ordinary contentment as deliberately dealt by Her hand, not as chance weather. Maternal giving defines Her economy: shelter ripens into gladness, and later names of delight and beatitude only unfold what this short name already promises to every child who turns toward Her. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 42.)", relatedVerseIds: ["ls-042"] },
  { id: "ls-nama-126", title: "Śāṅkarī", category: "Bhakti", summary: "She who gives happiness. Śam is joy and karī its maker, wedding Her to the Lord of joy whose office is bliss. The passage stresses utter parity of qualities between the divine pair, who together stand as father and mother of the universe; what He bestows She bestows, since parental joy has a single source in two forms. To approach one parent is to find both. Contemplate Her as the maternal face of the same happiness the Lord promises, and let prayer become homecoming. Two parents, one happiness: approaching Her maternal warmth therefore reaches His paternity too, and household prayer becomes audience with the universe's joint rulers. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 43.)", relatedVerseIds: ["ls-043"] },
  { id: "ls-nama-127", title: "Śrīkarī", category: "Bhakti", summary: "She who bestows riches in abundance. Śrī gathers wealth, beauty, attraction, and auspiciousness, and karī makes them; She both embodies and distributes every prosperity. The commentary parallels the Preserver's wealth-giving name, affirming no ultimate difference between brother and sister divinities, the elder Preserver and the Goddess, confirmed by later names hailing Her in His forms. Fortune is thus kinship. Contemplate wealth as Her ornament shared with children, asking less for gold than for the grace that rightly uses it. Ask less for hoarded gold than for beauty rightly shared, since fortune kept tight corrupts while fortune received as ornament multiplies joy for giver and receiver alike. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 43.)", relatedVerseIds: ["ls-043"] },
  { id: "ls-nama-128", title: "Sādhvī", category: "Bhakti", summary: "She who is chaste. Sādhvī praises perfect fidelity, Her abiding solely with Her Lord while regarding Him as divine. The passage untangles a hymn-verse where lordship over fortune, learning, and speech comes cheaply, yet She remains beyond all claimants save Śiva; lord here means owner or master of gifts, not husband, so Her exclusivity crowns rather than limits Her. Devotion mirrors marriage at its highest. Contemplate single-heartedness itself as worship, refusing divided allegiance in practice today. Her single-heartedness instructs the devotee: refuse divided allegiance in affection and in worship, and fidelity itself becomes the mirror in which She appears. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 43.)", relatedVerseIds: ["ls-043"] },
  { id: "ls-nama-129", title: "Śaraccandranibhānanā", category: "Bhakti", summary: "She whose face shines like the full moon in the clear autumn sky. Śarad is the bright autumn season when the moon rides stainless and full, and Her face is likened to that clarity. Seasonal and astral lore underlines the image: solar months grouped into seasons make autumn the crown of luminous calm, a beauty also praised elsewhere. Form here teaches serenity. Contemplate Her moon-face until mental weather clears and agitation settles into cool brightness. Cool brightness is the lesson: as autumn air clarifies the lunar disc, so lingering before Her face clarifies agitated thought until serenity itself becomes theology. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 43.)", relatedVerseIds: ["ls-043"] },
  { id: "ls-nama-130", title: "Śātodarī", category: "Bhakti", summary: "She who is slender-waister. Śāta suggests elegant slimness at the waist, a classic mark of feminine beauty. Joined with the preceding moon-face, the passage reads both names as glimpses of Her love-form to be unfolded later, where desire and meditation meet without contradiction. Beauty is theology in miniature. Contemplate slenderness as concentration itself, energy gathered rather than diffused. Slenderness pictures gathered force rather than thinness: energy conserved at the waist, neither scattered nor slack, teaches concentration as the bodily form of devotion. Beauty here remains contemplative, never ornamental: let gazing itself become meditation until beholder and beheld share one stillness. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 43.)", relatedVerseIds: ["ls-043"] },
  { id: "ls-nama-131", title: "Śāntimatī", category: "Bhakti", summary: "She who is peaceful. Śānti is forbearance that tolerates minor faults and never turns harsh without cause. Yet the passage sets a limit: persistent transgression invites correction through Her ministers, warrior goddesses who discipline where the Mother forebears. With this name the long arc of blessing closes, and the teaching turns toward the formless absolute first and qualified form afterward. Peace is patient but not passive. Contemplate Her tolerance as space for amendment, correcting one fault yourself before correction must come. Patience with room for amendment is Her method; use the spacious interval She grants to correct one fault yourself before sterner ministers must correct it. Bhakti is presented as both path and proof — feeling that verifies metaphysics. (Stotra verse 43.)", relatedVerseIds: ["ls-043"] },
  { id: "ls-nama-132", title: "Nirādhārā", category: "Nirguṇa", summary: "She who is without dependence. Nir-ādhārā denies every support, declaring She rests on nothing, not even Her own power. The passage cites the image of infinity established in itself and commends inward formless worship over outer Vedic or tantric rite, pure consciousness alone detaching the seeker from wandering and speeding Self-recognition. Supportlessness is sovereignty. Contemplate withdrawing one prop of approval or habit today, resting directly upon Her who needs none. Pure consciousness alone is sovereign, needing neither pedestal nor proof. Internal formless worship therefore outruns outer ceremony, detaching the seeker swiftly from wandering toward recognition. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 43.)", relatedVerseIds: ["ls-043"] },
  { id: "ls-nama-133", title: "Nirañjanā", category: "Nirguṇa", summary: "She who stays unattached, bound to nothing. Añjana is dark eye-salve that beautifies, and by extension the darkness of ignorance; with nir it yields stainless clarity needing no cosmetic. The passage refuses a merely human reading and identifies Her with the partless, actionless, calm, irreproachable, blemishless absolute, Her formless aspect likewise flawless, while in brow-center meditation early lights shed their spots through practice. Purity is original, not polished. Contemplate the mind's eye without liner, seeking clear light rather than decorated vision. Stainless clarity needs no cosmetic. Early gleams in brow-centered sitting may show spots, yet steady practice wipes the lens until original flawlessness stands revealed. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 43.)", relatedVerseIds: ["ls-043"] },
  { id: "ls-nama-134", title: "Nirlepā", category: "Nirguṇa", summary: "She who is free from all impurities arising from action. Lepa is stain or smear left by deeds, and its negation frees Her from karmic pollution. The passage offers two lights: She may enter a fit devotee's frame and remain untouched by its residues, indeed cleansing it, or like the teacher of duty without grasping She acts at Her Lord's direction and no fruit adheres, a pattern for yogins who labor visibly yet inwardly renounce. Action need not stain. Contemplate performing one duty today as assigned service, surrendering outcome before beginning. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-135", title: "Nirmalā", category: "Nirguṇa", summary: "She who is free from all impurities. Mala is the dirt of embodied limitation, the smallness-sense and ego-filth that disables free expression of the Self and breeds wandering. Where the prior name cleansed mental residue of acts, this one cleanses material identification itself: dissolving possessive ego dispels darkness and yields knowing, so every absolute-name indirectly enjoins meditation. Cleanliness is clarity. Contemplate one material clinging as mere dust on the mirror, wiping it by questioning who owns what. Ego-filth disables free expression of the Self and breeds wandering. Wiping the mirror by questioning ownership restores clarity, proving cleanliness to be another name for knowing. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-136", title: "Nityā", category: "Nirguṇa", summary: "She who is eternal. Nitya denies change and ending, marking the absolute as immutable and everywhere. The passage further notes fifteen lunar goddesses honored with the sacred diagram, each with seed-formula and special gift, crowned by a sixteenth who is the Goddess Herself as supreme festival-principle; later triple goddesses deepen the inward turn, with whole scriptural cycles devoted to them. Eternity wears time as ornament. Contemplate the lunar fortnight waxing and waning within changeless awareness, letting moods pass like phases. Time's phases wax and wane within changeless awareness. Let moods pass like lunar digits while the sixteenth, the Goddess Herself, remains the fullness they ornament. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-137", title: "Nirākarā", category: "Nirguṇa", summary: "She who is without form. Ākāra is shape and figure, whose denial states the formless absolute plainly. Among successive qualities of the qualityless, this stands central: whatever can be outlined can be limited, while She exceeds outline. Meditation must therefore outgrow depicting to arrive at being. Contemplate releasing one cherished image of the divine today, resting in presence without portraiture. Whatever can be outlined can be limited, while She exceeds every contour. Outgrowing depiction is therefore not loss but arrival, resting in presence without portraiture. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-138", title: "Nirākulā", category: "Nirguṇa", summary: "She who is without agitation. Ākulā is confusion, flurry, and disorder, all denied of Her. Though She originates the very bewilderment that veils seekers, like illusion-power She remains unruffled by it, cause without contagion. Agitation belongs to the wave, not the water. Contemplate tracing today's confusion back to its permitter rather than its trigger, and rest with the untroubled source. Waves may toss while water stays calm. Tracing confusion back to its permitter rather than its trigger returns attention to the untroubled source that authored even bewilderment. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-139", title: "Nirguṇā", category: "Nirguṇa", summary: "She who is beyond all three gunas of nature, namely sattva, rajas and tamas. Guṇa-threads weave luminosity, activity, and inertia into gross embodiment through the unwinding of primordial nature; having no gross frame, She stands beyond their equipoise, one self-shining God without second, unconditioned and attributeless. What binds souls as temperament cannot bind their source. Contemplate observing your dominant mood as weather of nature rather than identity of Self. Temperament binds souls, never their source. Watching the dominant mood as nature's weather rather than the Self's identity loosens the threads that weave embodiment. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-140", title: "Niṣkalā", category: "Nirguṇa", summary: "She who is without parts. Kalā is portion or digit, impossible in the partless. The passage extends the prior denial: living beings seem fragmentary only through conditioned life with its six senses including mind, while imageless, supportless lucidity alone counts as meditation, and souls are called parts merely apparently, since all such texts culminate in freedom from fault, age, death, hunger, and thirst through seeking the Self. Wholeness excludes pieces. Contemplate yourself as undivided awareness temporarily apparent as fragment, not as fragment seeking wholeness. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-141", title: "Śāntā", category: "Nirguṇa", summary: "She who is tranquil. Notably without negative prefix, the name affirms calm directly rather than by denial. Amid qualities established through not-this analysis, tranquillity is positively the nature of the absolute, impossible while bondage grips and essential for Self-recognition; peace, goodness, and unity converge in the fourth state beyond waking, dream, and sleep. Calm is not mood but being. Contemplate stilling one reactive impulse today as an offering to Her tranquillity. Bondage and quiet cannot share a seat. Stilling a single reactive impulse becomes offering, since peace here is not passing mood but the very being of the absolute. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-142", title: "Niṣkāmā", category: "Nirguṇa", summary: "She who is without desire. Kāma is want, whose absence explains the preceding calm, for craving and quiet cannot coexist. The passage aligns this with the great neither-this-nor-that inquiry culminating in truth-of-truth, and with infinity proceeding from infinity yet remaining infinite, a fullness needing nothing added. Desirelessness thus testifies to Her absolute status. Contemplate noticing one want without obeying it, tasting fullness that precedes fulfillment. Fullness precedes fulfillment: infinity proceeds from infinity yet remains infinite, so want testifies to forgetting rather than to lack. Notice craving without obeying it. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-143", title: "Nirupaplavā", category: "Nirguṇa", summary: "She who is indestructible. The name also carries a second hearing of nectar dripping toward the body when the coiled power nears the crown and floods seventy-two thousand channels. Perdurability and life-giving flow coincide: what cannot perish also nourishes what perishes, the same ascent that proves eternity distilling sustenance into nerves. Contemplate the crown as both imperishable sky and raining cloud, receiving steadiness and sweetness together. What cannot perish also nourishes what perishes. The same ascent that proves eternity distills sustenance, so the crown is simultaneously imperishable sky and raining cloud. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 44.)", relatedVerseIds: ["ls-044"] },
  { id: "ls-nama-144", title: "Nityamuktā", category: "Nirguṇa", summary: "She who is ever free from worldly bonds. Nitya-muktā means never bound at any time, another mark of the absolute. Freedom here is not achieved liberation but unbroken nature; to know Brahman one must share that unbound standing, since fetters cannot grasp the fetterless. Contemplate acting today as one already free rather than one earning freedom, letting duty lose its knot. Freedom here is unbroken nature, not prize. Acting as already free rather than as earning freedom lets duty lose its knot and service proceed without fetters. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 45.)", relatedVerseIds: ["ls-045"] },
  { id: "ls-nama-145", title: "Nirvikārā", category: "Nirguṇa", summary: "She who is unchanging. Vikāra is modification, denied of the witnessing consciousness that never alters while countless changes swirl around it. The passage contrasts the changeless seer with ever-transforming causal nature under its three strands, their conjunction birthing worlds through twenty-three principles from intellect and ego through subtle essences to senses, elements, and mind. She is the seer, not the stir. Contemplate standing as witness to one strong change today without becoming its accomplice. The seer never stirs while scenes revolve. Standing as witness to one strong change without becoming its accomplice rehearses the stillness behind twenty-three world-principles. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 45.)", relatedVerseIds: ["ls-045"] },
  { id: "ls-nama-146", title: "Niṣprapañcā", category: "Nirguṇa", summary: "She who is not of this universe. Prapañca is expansion and display, which She lacks because the complete first-without-beginning needs no unfolding. The passage hears the same teaching in the mantra of peace, goodness, non-duality, and the fourth state beyond the three familiar conditions, elaborated much later in the hymn; without development or division, She remains the silent background of all development. Contemplate the world as projection needing no change in its screen, and rest as screen rather than cinema. The screen never becomes the cinema. Resting as background while developments play across awareness discloses completeness that needs no expansion to be whole. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 45.)", relatedVerseIds: ["ls-045"] },
  { id: "ls-nama-147", title: "Nirāśrayā", category: "Nirguṇa", summary: "She who does not depend on anything. Āśraya is lodging and reliance, and its denial crowns Her as what all depends upon while depending on none. The passage invokes resting on nothing, free from modification, and the teaching that bodily decay never touches inner space where every true desire dwells; gross frame supporting soul cannot apply where there is no frame, only Brahman. Homelessness is all-housing. Contemplate leaning on Her rather than on circumstance, moving one reliance inward. Homelessness proves all-housing: what all depends upon depends on none. Moving one reliance from circumstance inward tests the support that never shakes. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 45.)", relatedVerseIds: ["ls-045"] },
  { id: "ls-nama-148", title: "Nityaśuddhā", category: "Nirguṇa", summary: "She who is eternally pure. Nitya-śuddhā joins permanence with stainlessness: impurity belongs to what alters, while Brahman never alters and therefore never soils. The gross frame may tarnish, but the purity embodied within it remains untouched, changelessness itself being cleansing. Contemplate purity as your native state rather than an achievement, letting one sense of stain dissolve for lack of owner. Tarnish belongs to frames, never to the embodied purity within. Recalling stainlessness as native state rather than achievement lets borrowed stains fall for lack of owner. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 45.)", relatedVerseIds: ["ls-045"] },
  { id: "ls-nama-149", title: "Nityabuddhā", category: "Nirguṇa", summary: "She who is ever wise. Buddhi here is not gathered information but inborn awakenedness, wisdom as essence rather than acquisition. Knowledge comes through experience and teachers, yet Her knowing never lapses because it is imperishable self-shining intelligence with no second object apart to be known. She knows by being. Contemplate learning as remembering Her wisdom within, approaching study as unveiling rather than accumulation. She knows by being, not by studying. Approaching learning as unveiling of Her inborn awakenedness within turns accumulation into remembrance and teachers into reminders. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 45.)", relatedVerseIds: ["ls-045"] },
  { id: "ls-nama-150", title: "Niravadyā", category: "Nirguṇa", summary: "She who is blameless or She who is praiseworthy. Avadya is reproach and defect, incapable of touching the eternally pure. Defects sprout from ignorance that discriminates perfect from faulty, fed by craving and ego; where no impurity of desire or self-assertion exists, transgression and dishonor find no foothold. Beyond blame lies praise. Contemplate withholding one act of fault-finding today, seeing imperfection as ignorance rather than essence. Beyond blame lies praise. Where craving and self-assertion cease, reproach finds no foothold, so withholding fault-finding becomes recognition of essence beneath imperfection. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 45.)", relatedVerseIds: ["ls-045"] },
  { id: "ls-nama-151", title: "Nirantarā", category: "Nirguṇa", summary: "She who is all-pervading. Antara covers middle, interval, and division, so its negation leaves no gaps, seams, or in-betweens. The passage stresses that Brahman neither divides nor multiplies, permanent across plant, insect, animal, and human alike, unmodified by time, distance, or creed; even the slightest self-separating discrimination breeds fear, which truly means renewed birth. Omnipresence forbids apartness. Contemplate closing one interval you keep from another being, recognizing the same presence on both sides. No gaps, seams, or in-betweens remain where She spreads. Closing one interval kept from another being acknowledges the same presence standing on both sides of every border. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 45.)", relatedVerseIds: ["ls-045"] },
  { id: "ls-nama-152", title: "Niṣkāraṇā", category: "Nirguṇa", summary: "She who is without cause. Kāraṇa is antecedent source, which She lacks while being the blissful elemental ground from which worlds manifest. The passage cites the ruler with no master, controller, or identifying mark, cause of all yet caused by none, lord of souls and senses. Uncaused, She causes. Contemplate tracing effects backward until questioning itself rests in what needs no before. Uncaused, She causes. Tracing effects backward until questioning itself rests discloses the blissful elemental ground that needs no before in order to begin all things. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 46.)", relatedVerseIds: ["ls-046"] },
  { id: "ls-nama-153", title: "Niṣkalaṅkā", category: "Nirguṇa", summary: "She who is faultless. Kalaṅka is stain left by wrongdoing, and sinlessness makes Godlikeness vanishingly rare. The passage describes the absolute as pure and unpierced by evil, duality being the root of fault, with anger, hatred, and envy filming over inner recognition. She bears no such film. Contemplate one resentment as a smudge on your own lens, cleaning vision by releasing the charge. Duality films the lens with anger, hatred, and envy. Releasing one resentment as smudge on your own seeing cleans vision faster than accusing the image. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 46.)", relatedVerseIds: ["ls-046"] },
  { id: "ls-nama-154", title: "Nirupādhiḥ", category: "Nirguṇa", summary: "She who is not conditioned or has no limitations. Upādhi is the adjacent attribute that makes the limitless look limited, like sky seemingly boxed or clear crystal reddened by a neighboring flower. Ignorance works exactly so, tinting speech and conduct. The passage pictures transparent stillness beside Her rosy dynamism, mistaken by lesser gods for sunrise, a delightful emblem of how adjuncts color perception while Brahman stays beyond limit. Contemplate distinguishing the crystal from its borrowed red in one heated reaction today. Learn to separate crystal from borrowed red. In one heated reaction today, distinguish limitless awareness from its adjacent tint of ignorance before speech obeys the color. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 46.)", relatedVerseIds: ["ls-046"] },
  { id: "ls-nama-155", title: "Nirīśvarā", category: "Nirguṇa", summary: "She who has no superior or protector. Īśvara is master above, which She lacks as supreme ruler. The passage meets the objection about Her Lord by assigning Him creation of energy and still witnessing partnership without interference in Her administrative play, hence no overlord in function. With this name the exposition of absolute qualities closes: common minds approach the imperceptible through denial, beginning with not-that and ripening into I-am-That, affirmation earned only by complete knowing. Contemplate obeying Her governance directly, without appealing over Her head. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 46.)", relatedVerseIds: ["ls-046"] },
  { id: "ls-nama-156", title: "Nīrāgā", category: "Nirguṇa", summary: "She who has no desire. Rāga is coloring attraction, absent in Her. Though resembling earlier denials, the passage shifts ground from describing the absolute to prescribing its attainment: fourfold inner instrument of mind, intellect, manifested awareness, and ego, plus six poisons of craving, anger, jealousy, bewilderment, pride, and envy, all obstruct recognition though none touch the Self. Technique now follows theology. Contemplate naming which inner instrument loudest colors your seeing today, and disown its tint. Technique now follows theology. Naming which inner instrument loudest colors perception, then disowning its tint, turns self-observation into the first step of attainment. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 46.)", relatedVerseIds: ["ls-046"] },
  { id: "ls-nama-157", title: "Rāgamathanī", category: "Nirguṇa", summary: "She who destroys desires (passions). Mathanī churns and crushes, here the cravings of devotees, first fruit of worshipping the formless. Craving is named the root fetter fastening worldly bonds, counted by yoga among the five pain-breeding obstacles beginning with ignorance and continuing through ego, attraction, aversion, and clinging to life. She churns the obstacle itself. Contemplate offering one specific craving to be churned rather than indulged or suppressed. Craving fastens worldly bonds and breeds pain through ignorance, ego, attraction, aversion, and clinging. Offering one specific hunger to be churned invites Her crushing mercy. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 46.)", relatedVerseIds: ["ls-046"] },
  { id: "ls-nama-158", title: "Nirmadā", category: "Nirguṇa", summary: "She who is without pride. Mada is the intoxication of possessing what others lack. Since everything issues from Her as from the golden womb of imperishable substance celebrated in ancient hymn, comparison collapses and pride finds no second to surpass. All-having leaves nothing to boast. Contemplate tracing one advantage back to its common source until superiority dissolves into gratitude. Comparison collapses where all issues from one golden womb. Tracing one advantage back to its common source dissolves superiority into gratitude and intoxication into sobriety. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 46.)", relatedVerseIds: ["ls-046"] },
  { id: "ls-nama-159", title: "Madanāśinī", category: "Nirguṇa", summary: "She who destroys pride. What She exemplifies She imparts, annihilating devotees' arrogance as precondition for recognition. The pattern is precept by example: being without pride, She requires the same clearing in those approaching Her. Humility is thus conformity to Her nature. Contemplate letting one success pass without signature today, giving its authorship to Her. Precept comes by example: being without pride, She requires the same clearing in approachers. Letting one success pass without signature returns authorship to its true owner. Conformity to Her nature is the whole method: humility practiced daily aligns the devotee with the pride-free absolute. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 46.)", relatedVerseIds: ["ls-046"] },
  { id: "ls-nama-160", title: "Niścintā", category: "Nirguṇa", summary: "She who has no anxiety in anything. Cintā is worry that replays the past, impossible for One beyond time and space with no bygone to haunt. The passage adds a charming administrative image: She wisely delegates cosmic labor to ministers like the hog-faced and dark-blue goddesses honored in diagram worship, confirming Her overlordship by ease itself. Delegation proves dominion. Contemplate entrusting one gnawing yesterday to timelessness, refusing its replay. Timelessness keeps no diary. Entrusting one gnawing yesterday to what has no past refuses its replay and confirms overlordship through ease rather than effort. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 47.)", relatedVerseIds: ["ls-047"] },
  { id: "ls-nama-161", title: "Nirahaṅkārā", category: "Nirguṇa", summary: "She who is without egoism. She who is without the concept of 'I' and 'mine'. Ahaṅkāra is the knot of I-and-mine woven from the three strands of lucidity, passion, and inertia; lacking those strands, She lacks their knot. The former absolute-denial already implied this, now sharpened as remedy: ego-lessness becomes the devotee's medicine. Contemplate catching one possessive pronoun today and hearing how much burden it carries. Possessive pronouns carry heavy loads. Catching one I or mine today and hearing its burden exposes the knot woven from lucidity, passion, and inertia before it tightens. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 47.)", relatedVerseIds: ["ls-047"] },
  { id: "ls-nama-162", title: "Nirmohā", category: "Nirguṇa", summary: "She who is free from delusion. Moha is bewilderment, infatuation, and distraction, all offspring of mind. Only mind attuned to thoughtlessness opens Self-recognition, where love and hate lose footing before oneness; poise amid praise and blame, earth-lump, stone, and gold alike, marks transcendence of nature's moods, gathering freedom from worry, ego, and confusion into one steadiness. Contemplate meeting one attraction and one repulsion with exactly equal gaze. Love and hate lose footing before oneness. Meeting one attraction and one repulsion with exactly equal gaze steadies the mind toward the thoughtlessness in which recognition dawns. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 47.)", relatedVerseIds: ["ls-047"] },
  { id: "ls-nama-163", title: "Mohanāśinī", category: "Nirguṇa", summary: "She who destroys delusion in Her devotees. Clearing confusion advances the path, since seeing the same reality everywhere dissolves infatuation. The passage teaches that energy-veil, also called enchantment, alone can escort the seeker to the still ground and then step aside, leaving him before self-shining awareness to recognize directly. Her withdrawing is Her giving. Contemplate asking Her to lift one specific bewilderment rather than to grant one specific favor. Her withdrawing is Her giving: the veiling energy escorts the seeker to still ground, then steps aside before self-shining awareness. Request clarity rather than favors. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 47.)", relatedVerseIds: ["ls-047"] },
  { id: "ls-nama-164", title: "Nirmamā", category: "Nirguṇa", summary: "She who has no self-interest in anything. Mamatā is mine-concern that splits knower from absolute into duality. Read through the opening Mother-name, the same absence becomes maternal selflessness: the supreme parent cares nothing for Herself and everything for living children. Negation and motherhood meet. Contemplate converting one self-concern into care for another being today. Negation and motherhood meet here. Converting one self-concern into care for another being turns metaphysical denial into maternal practice without changing its truth. Mine-concern splits knower from absolute, so maternal selflessness practiced toward living children mends the philosophical rift in daily life. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 47.)", relatedVerseIds: ["ls-047"] },
  { id: "ls-nama-165", title: "Mamatāhantrī", category: "Nirguṇa", summary: "She who destroys the sense of ownership. Hantrī slays possessiveness in devotees, since self-interest breeds the ego that blocks recognition. Here begins the paired rhythm where one name denies a fault in Her and the next destroys it in worshippers, doctrine alternating with grace. Contemplate loosening grip on one owned thing or person, holding it as trustee rather than proprietor. Doctrine now alternates with grace: one name denies a fault in Her, the next destroys it in worshippers. Holding one possession as trustee rather than proprietor joins that rhythm. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 47.)", relatedVerseIds: ["ls-047"] },
  { id: "ls-nama-166", title: "Niṣpāpā", category: "Nirguṇa", summary: "She who is without sin. Pāpa is wrong born of craving, and craving She already lacks, while the teacher of the battlefield likewise claims no work taints Him nor fruit entices. Sinlessness follows desirelessness as effect follows cause. Contemplate tracing one fault back to its craving-root, starving root rather than pruning act. Effect follows cause: where craving ends, wrong cannot begin. Starving the craving-root rather than pruning the guilty act prevents sin before it seeks forgiveness. Craving mothers wrong, hence desirelessness guarantees innocence. Starving the root prevents sin before it can seek forgiveness or excuse. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 47.)", relatedVerseIds: ["ls-047"] },
  { id: "ls-nama-167", title: "Pāpanāśinī", category: "Nirguṇa", summary: "She who destroys all the sins of Her devotees niṣkrodhā. Nāśinī consumes devotees' wrongs so they may walk toward freedom unladen. Devotee here means one who remembers Her constantly beyond mantra-hours and rites, for whom techniques grow unnecessary, and deliberate wrong forfeits rescue; understanding Her untaintedness loosens entanglement in results, while all faults are said to burn like dry grass in fire, save ripening destiny that must still be lived through. Contemplate sincerity as the true fuel that lets old residues burn. Sincerity is the fuel that lets old residues burn like dry grass, sparing only ripening destiny that must still be lived through. Remember Her constantly, not merely hourly. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 47.)", relatedVerseIds: ["ls-047"] },
  { id: "ls-nama-168", title: "Niṣkrodhā", category: "Nirguṇa", summary: "She who is without anger. Krodha is wrath, absent even amid dissolution, like a mirror that shows only who stands before it. None is hateful and none dear to the absolute; devotion reveals grace while indifference merely misses it, never provoking Her. Equanimity is not coldness but completeness. Contemplate meeting one provocation as mirror rather than flame, reflecting without igniting. The mirror shows only who stands before it, igniting nothing. Meeting provocation as reflection rather than flame keeps equanimity complete without turning cold. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 48.)", relatedVerseIds: ["ls-048"] },
  { id: "ls-nama-169", title: "Krodhaśamanī", category: "Nirguṇa", summary: "She who destroys anger in Her devotees. Śamanī pacifies wrath, counted among the six obstructions with craving, jealousy, bewilderment, pride, and envy; worship performed in anger is said to forfeit its fruit. The passage traces anger from sense-dwelling through attachment and craving to ruin, driven by restless passion, so sense-restraint becomes devotion's guardrail. Contemplate pausing between stimulus and response once today, letting Her cool the interval. Sense-dwelling ripens through attachment and craving into ruin. Pausing between stimulus and response, letting Her cool the interval, guards devotion better than resolve alone. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 48.)", relatedVerseIds: ["ls-048"] },
  { id: "ls-nama-170", title: "Nirlobhā", category: "Nirguṇa", summary: "She who is without greed. Lobha is grasping excess, foreign to One extremely liberal toward devotees. Having all, She needs none; giving all, She keeps none. Contemplate answering one grasping impulse with deliberate generosity. Having all, She needs none; giving all, She keeps none. Answering one grasping impulse with deliberate generosity copies Her liberality and starves the excess at its root. Grasping excess contradicts Her extreme liberality. Copying Her openhandedness in one concrete gift today starves acquisitiveness and proves abundance to be Her nature, not Her mood. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 48.)", relatedVerseIds: ["ls-048"] },
  { id: "ls-nama-171", title: "Lobhanāśinī", category: "Nirguṇa", summary: "She who destroys greed in Her devotees. Greed is named one of three gates to ruin alongside craving and anger, degrading the soul and therefore targeted by Her grace. Liberality in the Goddess demands liberality in the child. Contemplate closing one gate today by wanting less rather than having more. Craving, anger, and greed open three gates to ruin and degrade the soul. Wanting less today rather than having more closes one gate by Her destroying grace. Degradation follows the triple gate, so closing greed by deliberate contentment invites Her destroying grace and steadies the soul upward. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 48.)", relatedVerseIds: ["ls-048"] },
  { id: "ls-nama-172", title: "Niḥsaṃśayā", category: "Nirguṇa", summary: "She who is without doubts. Saṃśaya is questioning that seeks knowing, impossible where She is knowing embodied. Uncertainty belongs to learners, not to the lesson itself. Contemplate resting one inquiry in Her certainty rather than in further argument. Uncertainty belongs to learners, never to the lesson. Resting one inquiry in Her certainty rather than in further argument lets questioning ripen into quiet confidence. The embodiment of knowledge cannot hesitate. Committing one unsettled question to Her certainty lets inquiry ripen into quiet, doubt-free confidence. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 48.)", relatedVerseIds: ["ls-048"] },
  { id: "ls-nama-173", title: "Saṃśayaghnī", category: "Nirguṇa", summary: "She who kills all doubts. Ghnī slays devotees' uncertainties, for embodied wisdom can resolve what texts only pose. The passage pictures Her assuming the teacher's form, the true preceptor being doubtless, instantly clarifying, and expecting no price, since spirituality cannot be sold though disciples should sustain their teachers within measure; realizing cause and effect as one's own Self ends peculiarities and disperses questioning, approached through humble service and guileless inquiry. Contemplate carrying one honest doubt to a worthy teacher instead of nursing it. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 48.)", relatedVerseIds: ["ls-048"] },
  { id: "ls-nama-174", title: "Nirbhavā", category: "Nirguṇa", summary: "She who is without origin. Bhava is birth and becoming, which She never entered, first yet parentless like Her Lord with whom She is non-different in unified absolute. Neither existent-object nor nonexistent-void captures that beginningless lordship over beginnings. Originlessness founds all origins. Contemplate your own awareness as unborn amid born thoughts, resting before commencement. Originlessness founds all origins. Resting as unborn awareness amid born thoughts places attention before commencement, where neither object nor void can capture lordship. Parentless and first, She founds every lineage. Abiding briefly as unborn awareness steadies all born thoughts in their proper motion. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 48.)", relatedVerseIds: ["ls-048"] },
  { id: "ls-nama-175", title: "Bhavanāśinī", category: "Nirguṇa", summary: "She who destroys the sorrow of samsāra (the cycle of birth and death). Bhava here is the revolving round itself, bondage as its own punishment. Worship of the formless is said to free from that wheel, exclusive self-giving devotion lifting seekers from the ocean of becoming, with solemn fire-offerings on the ninth lunar day likewise praised for dissolving worldly affliction. True devotion defines itself by surrender. Contemplate surrendering one action's fruit to Her today as passage out of recurrence. Bondage is its own punishment and surrender its passage. Giving one action's fruit to Her today rehearses the exclusive self-offering that lifts seekers from the ocean of becoming. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 48.)", relatedVerseIds: ["ls-048"] },
  { id: "ls-nama-176", title: "Nirvikalpā", category: "Nirguṇa", summary: "She who is free of false imaginings. Vikalpa is the horned-horse fiction, word without object, and by extension every sorting by name, shape, and class; meditative speech calls indeterminate perception and finally seedless absorption where seer and seen cease to divide. Read as against-theory, the name also affirms there is no counter-thesis to Her absoluteness, nothing separable from Her, formless emphasis being the dominant scriptural note. Contemplate dropping one label you habitually glue onto persons, meeting them unclassified. Word without object breeds horned horses. Dropping one habitual label glued onto persons lets them appear unclassified, inseparable from the awareness that beholds them. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 49.)", relatedVerseIds: ["ls-049"] },
  { id: "ls-nama-177", title: "Nirābādhā", category: "Nirguṇa", summary: "She who is not disturbed by anything. Ābādhā is obstruction and harassment by mis-taking, like rope feared as snake with its train of craving and dread. Being Herself the source of such measuring illusion, She cannot suffer it, and qualityless Brahman admits no disturbance at all. Cause stands clear of effect. Contemplate examining one fright until the rope shows beneath the snake. Cause stands clear of effect. Examining one fright until rope shows beneath imagined snake returns the mind from mis-taking to the undisturbed measurer of illusion. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 49.)", relatedVerseIds: ["ls-049"] },
  { id: "ls-nama-178", title: "Nirbhedā", category: "Nirguṇa", summary: "She who is beyond all sense of difference. Bheda is the split, perhaps especially between Lord and Lady, which the wise refuse; their combine alone is the absolute whose qualities this whole hymn celebrates, neither partner acting without the other. Address to Her is always address to the pair. Contemplate refusing one sacred-versus-profane split today, serving the same presence in both. Address to Her is always address to the pair. Refusing one split between sacred and profane serves the same presence in both halves of a falsely divided day. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 49.)", relatedVerseIds: ["ls-049"] },
  { id: "ls-nama-179", title: "Bhedanāśinī", category: "Nirguṇa", summary: "She who removes from Her devotees all sense of differences born of vāsanās. Latent tendencies manufacture duality, and She destroys that manufacture by granting knowledge. The passage notes the hymn's own finale promising non-difference between Goddess and devotee, those closing directions on recitation, timing, and fruit being the traditional seal upon every great praise-song. Difference ends in identity. Contemplate tracing one us-versus-them feeling to its stored impression, asking Her knowledge to dissolve it. Latent tendencies manufacture duality; granted knowledge demolishes the factory. Tracing one us-versus-them feeling to its stored impression invites Her dissolving instruction. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 49.)", relatedVerseIds: ["ls-049"] },
  { id: "ls-nama-180", title: "Nirnāśā", category: "Nirguṇa", summary: "She who is imperishable. Nāśa is destruction, forever inapplicable to infinity, whose very titles are truth, knowledge, and endlessness. What never began cannot end. Contemplate anchoring one anxious plan in what outlasts every plan. What never began cannot end. Anchoring one anxious plan in what outlasts every plan steadies effort, since infinity lends weight to finite undertaking without sharing its fragility. Infinity answers to truth, knowledge, and endlessness together. Entrusting one fragile undertaking to the imperishable lends it weight no contingency can supply. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 49.)", relatedVerseIds: ["ls-049"] },
  { id: "ls-nama-181", title: "Mṛtyumathanī", category: "Nirguṇa", summary: "She who destroys death. Mṛtyu is decease and its sequel rebirth, both churned away for devotees; only the deathless can grant deathlessness, by consuming the stored actions that compel return. Devotee here means not ritualist but one identified with Her through unbroken meditation. Practice becomes identity. Contemplate meditating until meditator, act, and Mother briefly coincide, rehearsing deathlessness. Practice becomes identity here: the true devotee is one identified with Her through unbroken meditation, not a performer of rites. Briefly coinciding with Her rehearses deathlessness itself. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 49.)", relatedVerseIds: ["ls-049"] },
  { id: "ls-nama-182", title: "Niṣkriyā", category: "Nirguṇa", summary: "She who remains without action. Kriyā is engagement, paradoxical for kinetic energy and reflective aspect of the absolute who yet as formless witness never engages. The passage resolves it doubly: bodiless awareness stands clear of good and evil deeds that touch only frames, while Self-abiders, though embodied, no longer count body as self and hence gather no residue, delighting in Self alone beyond obligatory duty. Inaction is non-identification, not inertia. Contemplate doing necessary work today while inwardly standing aside as witness. Inaction means non-identification, never inertia. Doing necessary work while inwardly standing aside delights in the Self alone and gathers no residue for the soul. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 49.)", relatedVerseIds: ["ls-049"] },
  { id: "ls-nama-183", title: "Niṣparigrahā", category: "Nirguṇa", summary: "She who does not acquire or accept anything. Parigraha is taking return for deeds, which She renounces though ceaselessly creating, sustaining, and dissolving; without Her least act the world would lapse, yet no offering of flower or food repays Her. Ritual is thus only a ladder toward recognition, dangerous to inhabit permanently. Contemplate converting one offering from payment into remembrance, giving without settling accounts. Ladders are for climbing, not inhabiting. Converting one offering from payment into remembrance honors ceaseless cosmic action while renouncing all claim to return. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 49.)", relatedVerseIds: ["ls-049"] },
  { id: "ls-nama-184", title: "Nistulā", category: "Nirguṇa", summary: "She who is incomparable, unequalled. Tulā is balance-scale likeness, impossible where no second exists to weigh against the supreme. A later name will echo the same incomparability. Contemplate abandoning one comparison by which you measure yourself against another, standing unscaled before Her. No second exists to weigh against the supreme, so scales stay empty. Abandoning one self-measurement against another leaves standing unscaled before incomparable majesty. Later praise will echo this peerlessness. Standing unscaled and unmeasured before majesty ends comparison and leaves only wonder in its place. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 50.)", relatedVerseIds: ["ls-050"] },
  { id: "ls-nama-185", title: "Nīlacikurā", category: "Nirguṇa", summary: "She who has shining black hair. Nīla is deep indigo and cikurā locks, startling amid formless praises yet deliberately set there. The passage puzzles honestly: perhaps seers, absorbed in absoluteness, flashed upon Her beauty, celebrated elsewhere in locks dark as rainclouds; esoterically indigo marks the brow wheel and its hidden rear center above the medulla, seat of far-seeing and cosmic communion veiled by the tuft, whose mountain-like rise when awakened hints at secret ascent. Form glints within formlessness. Contemplate the back of the head as moonlit night wherein hidden sight wakes. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 50.)", relatedVerseIds: ["ls-050"] },
  { id: "ls-nama-186", title: "Nirapāyā", category: "Nirguṇa", summary: "She who is imperishable. Apāya is ruin and dissolution, forever absent from Brahman. Where a twin name stressed endurance, this one bars even approach of ending. Contemplate building one hope upon what cannot be demolished. Ruin cannot even approach, let alone touch. Building one hope upon what cannot be demolished trades fragile optimism for grounded confidence in the enduring. Even the approach of ending is barred, not merely its arrival. Grounding daily confidence firmly in the truly undemolishable turns fragile optimism into steady assurance. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 50.)", relatedVerseIds: ["ls-050"] },
  { id: "ls-nama-187", title: "Niratyayā", category: "Nirguṇa", summary: "She who cannot be transgressed. Atyaya is overstepping bounds, which She never commits, enacting yet never violating Her own law of consequence. Self-limitation becomes example: the lawgiver obeys Her law. Contemplate honoring one limit you yourself set, keeping faith as She keeps Hers. The lawgiver obeys Her own law of consequence, setting example by self-limitation. Honoring one limit you yourself set keeps faith as She keeps Hers. Self-limitation crowns sovereignty: keeping one self-imposed boundary faithfully mirrors the lawgiver who obeys Her own decree. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 50.)", relatedVerseIds: ["ls-050"] },
  { id: "ls-nama-188", title: "Durlabhā", category: "Nirguṇa", summary: "She who is won only with much difficulty. Dur-labha concedes attainability while warning of cost: no outer rite purchases Her, only dedicated inward search and steady meditation that climbs into higher awareness. Difficulty guards intimacy. Contemplate substituting one outward observance with ten minutes of silent inward seeking. Difficulty guards intimacy: no outer purchase secures Her. Trading one external observance for silent inward seeking tests whether persistence can open what price cannot. Inner search alone purchases intimacy. Lengthening silent sitting by a few minutes daily tests whether persistence can open what display cannot. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 50.)", relatedVerseIds: ["ls-050"] },
  { id: "ls-nama-189", title: "Durgamā", category: "Nirguṇa", summary: "She who is approachable only with extreme effort. Dur-gamā stresses the road: discipline must meditate Her self-shining triple person, gross, lovely-subtle, and coiled-subtlest, since rites alone never arrive. Worship should begin with ceremony and graduate into absorption; when transformation occurs She turns accessible, no-longer-hard-to-reach. Effort ends in ease. Contemplate taking one ritual you perform and interiorizing its meaning for a week. Effort ripens into ease when ceremony graduates into absorption. Interiorizing one rite's meaning for a week turns hardness into approachability and discipline into welcome. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 50.)", relatedVerseIds: ["ls-050"] },
  { id: "ls-nama-190", title: "Durgā", category: "Nirguṇa", summary: "She who is the Goddess Ḍurgā. Dur-gā is she who carries across difficulty, fiery and radiant protectress celebrated in her own hymn. Those who shelter in Her are ferried over trouble as by boat across flood, with triple recitation of her litany, death-conquering formula, and solar illumination counted as a hundred seeds that repel misery; protection covers mind and body together, poise required for inward search. Contemplate invoking the fortress-goddess before meditation, asking safe passage through restlessness. Fortress and ferry coincide in Her: fiery radiance that daunts trouble also carries the sheltered across flood. Invoking Her before sitting steadies both body and mind for inward search. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 50.)", relatedVerseIds: ["ls-050"] },
  { id: "ls-nama-191", title: "Duḥkhahantrī", category: "Nirguṇa", summary: "She who is the destroyer of sorrow. Duḥkha-suffering flows from world-bondage mistaken for family management, attachment and craving dragging swimmers into an ocean hard to cross. True freedom is release from sense-contact misery for those unattached to matter. She slays sorrow by severing its root. Contemplate naming one attachment-born ache and stepping back to shore rather than swimming farther out. Mistaking bondage for family drags swimmers outward. Naming one attachment-born ache and stepping back to shore chooses dry ground over deeper drowning in the ocean of recurrence. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 50.)", relatedVerseIds: ["ls-050"] },
  { id: "ls-nama-192", title: "Sukhapradā", category: "Nirguṇa", summary: "She who is the giver of happiness. Sukha here is not pleasure after pain removed but deathless beatitude of no further birth, reserved for those who have tasted Self as sweetness and its source, glad ones chosen by discipline under impartial law. Selection follows practice, never favoritism. Contemplate practicing as qualification rather than petition, becoming the gladness you request. Selection follows practice, never favoritism. Becoming the gladness requested, through discipline under impartial law, qualifies the seeker for beatitude beyond rebirth. Impartial law selects the disciplined glad. Practicing as qualification rather than petition makes the seeker the very happiness requested. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 50.)", relatedVerseIds: ["ls-050"] },
  { id: "ls-nama-193", title: "Duṣṭadūrā", category: "Nirguṇa", summary: "She who is unapproachable by sinners. Duṣṭa are the spoiled and corrupt who never turn thought toward Her, hence never reach liberation. Distance here is self-imposed exile, not Her refusal. Contemplate one corrupting habit as distance itself, shortening it by a single turn toward Her. Distance here is self-imposed exile, never Her refusal. Shortening one corrupting habit by a single turn toward Her proves the far to have been near all along. Exile is self-decreed, never imposed. One honest turn shortens the distance that corruption lengthened, proving the far to be near. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 51.)", relatedVerseIds: ["ls-051"] },
  { id: "ls-nama-194", title: "Durācāraśamanī", category: "Nirguṇa", summary: "She who stops evil customs. Dur-ācāra is conduct forbidden by revelation, including recent costly innovations without scriptural root or spiritual yield. The passage contrasts extravagant performance beyond means with a minute of deep devotion, urging tradition tested by scripture over hype. She stills corruption by restoring measure. Contemplate replacing one expensive gesture with one minute of heartfelt prayer. She stills corruption by restoring measure. Replacing one expensive gesture with heartfelt brevity obeys revelation over hype and lets devotion outweigh display. Restored measure stills corruption. Trading display for heartfelt brevity lets a minute of devotion outweigh costly performance. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 51.)", relatedVerseIds: ["ls-051"] },
  { id: "ls-nama-195", title: "Doṣavarjitā", category: "Nirguṇa", summary: "She who is free from all faults. Doṣa is blemish of mind such as hatred and craving, never merely bodily. With this name the fruits of formless worship conclude and qualified worship begins, formless contemplation ranked higher yet formed devotion grounding most faiths. Faultlessness qualifies Her to cleanse fault. Contemplate offering one mental blemish for cleansing rather than concealing it. Faultlessness qualifies the cleanser. Offering one mental blemish for washing rather than concealing it completes formless worship and opens the gate to qualified forms. Apophatic names are surgical: each nir- severs one identification, each -nāśinī heals the wound. (Stotra verse 51.)", relatedVerseIds: ["ls-051"] },
  { id: "ls-nama-196", title: "Sarvajñā", category: "Sarva-mahā", summary: "She who is omniscient. Sarva-jñā knows all universally and in detail, possible only for Brahman. The passage cites the teaching that from austerity-knowledge, understood as supreme penance-meditation, higher and lower Brahman proceed with name, form, and nourishment; formless and formed are thus two poises of one knowing. Contemplate being thoroughly known by Her before trying to know, relaxing concealment. Formless and formed are two poises of one knowing. Relaxing concealment before Her thorough knowledge lets being known precede knowing, and penance-ripened meditation complete the circuit. Sarva names assert pervasion; mahā names assert unsurpassability — immanence and transcendence in one breath. (Stotra verse 51.)", relatedVerseIds: ["ls-051"] },
  { id: "ls-nama-197", title: "Sāndrakaruṇā", category: "Sarva-mahā", summary: "She who shows intense compassion. Sāndra is dense, unbroken pity befitting the universal Mother for whom all are children and portions of the One. The passage borrows a modern seer's portrait: inexhaustible mercy whose refusals are postponements and punishments grace, yet never blinding wisdom nor deflecting lawful action. Compassion obeys truth. Contemplate receiving one refusal as delayed mercy, trusting Her timing over your schedule. Refusals here are postponements and punishments grace, yet wisdom stays unblinded and lawful action unbent. Receiving one denial as delayed mercy trusts Her timing over impulse. Sarva names assert pervasion; mahā names assert unsurpassability — immanence and transcendence in one breath. (Stotra verse 51.)", relatedVerseIds: ["ls-051"] },
  { id: "ls-nama-198", title: "Samānādhikavarjitā", category: "Sarva-mahā", summary: "She who has neither equal nor superior. Sama denies peer and adhika denies better, leaving Her incomparable in might across all worlds. The passage hears the same claim in teachings of a bodiless, organless absolute wielding manifold powers of knowing and acting, and in the awestruck address to the charioteer-Lord as peerless. Uniqueness is not pride but fact. Contemplate ranking no power beside Her today, referring every help upward to its source. Uniqueness is fact, not boast. Referring every help upward to its single source today dethrones rival powers and honors the peerless might behind all worlds. Sarva names assert pervasion; mahā names assert unsurpassability — immanence and transcendence in one breath. (Stotra verse 51.)", relatedVerseIds: ["ls-051"] },
  { id: "ls-nama-199", title: "Sarvaśaktimayī", category: "Sarva-mahā", summary: "She who has all the divine powers (she who is omnipotent). Sarva-śakti-mayī consists of every energy, using divine force for creation, maintenance, and withdrawal. The passage reads powers concretely as minister-goddesses and ten wisdom-forms serving under Her command, while literally She is all of them through omnipresence, rightly titled Energy itself. Command and identity coincide. Contemplate meeting any formidable force as Her delegated energy, approaching the delegate through its Mistress. Command and identity coincide: ministers and wisdom-forms serve Her yet are Her through omnipresence. Meeting any formidable force as delegated energy leads approach to its Mistress. Sarva names assert pervasion; mahā names assert unsurpassability — immanence and transcendence in one breath. (Stotra verse 52.)", relatedVerseIds: ["ls-052"] },
  { id: "ls-nama-200", title: "Sarvamaṅgalā", category: "Sarva-mahā", summary: "She who is the source of all that is auspicious. Sarva-maṅgalā embodies every blessing, addressed elsewhere as the auspicious Lord in feminine form and praised in the famous salutation to the three-eyed creatress-sustainer-dissolver, ever-existent, virtue-formed, refuge of all aims. Source of welfare, She readily deals welfare to devotees, a name shared with the shorter three-hundred litany. Contemplate beginning undertakings by touching Her auspiciousness, letting Her virtue shape their aim. Virtue-formed and refuge of all aims, She deals welfare readily to devotees. Touching Her auspiciousness before beginning lets Her excellence shape both means and end. Sarva names assert pervasion; mahā names assert unsurpassability — immanence and transcendence in one breath. (Stotra verse 52.)", relatedVerseIds: ["ls-052"] },
];
